      "content": "{\n  \"name\": \"dsh-crypto-portfolio\",\n  \"version\": \"0.2.0\",\n  \"description\": \"Self-hosted crypto portfolio dashboard as a DSH plugin: Bitcoin, EVM (73 chains), Solana, Dogecoin, Cardano, Hyperliquid L1 and read-only CEX accounts in one view. Zero-dependency web UI (Python stdlib + vanilla JS).\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"files\": [\n    \"index.js\",\n    \"cordis.patch.yml\",\n    \"tracker\",\n    \"static\",\n    \"run.py\",\n    \"fetch.py\",\n    \"templates\",\n    \"requirements.txt\",\n    \"CHANGELOG.md\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"deepseek-harness\",\n    \"crypto\",\n    \"portfolio\",\n    \"tracker\",\n    \"dashboard\",\n    \"self-hosted\",\n    \"bitcoin\",\n    \"ethereum\",\n    \"evm\",\n    \"solana\",\n    \"dogecoin\",\n    \"cardano\",\n    \"hyperliquid\",\n    \"debank\",\n    \"binance\",\n    \"bybit\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/0xRabit/dsh-crypto-portfolio.git\"\n  },\n  \"license\": \"MIT\"\n}\n"
