      "path": "tracker/storage.py",
      "content": "# -*- coding: utf-8 -*-\n\"\"\"SQLite storage: daily snapshots (last result of each day) + token/wallet detail rows.\"\"\"\nimport json\nimport os\nimport sqlite3\nimport threading\nfrom datetime import datetime, timedelta\n\nfrom . import config, profiles\nfrom . import blacklist as blacklist_mod\nfrom .blacklist import filter_rows\nfrom . import assetlabels as assetlabels\nfrom .views import view_of\n\n_here = os.path.dirname(os.path.abspath(__file__))\n_ROOT = os.path.dirname(_here)\n\nSCHEMA = \"\"\"\nCREATE TABLE IF NOT EXISTS snapshots (\n    date         TEXT PRIMARY KEY,\n    created_at   TEXT NOT NULL,\n    total_usd    REAL NOT NULL DEFAULT 0,\n    by_chain     TEXT NOT NULL DEFAULT '{}',\n    raw          TEXT NOT NULL DEFAULT '{}'\n);\nCREATE TABLE IF NOT EXISTS wallet_totals (\n    date   TEXT NOT NULL,\n    wallet TEXT NOT NULL,\n    usd    REAL NOT NULL DEFAULT 0,\n    PRIMARY KEY (date, wallet)\n);\nCREATE TABLE IF NOT EXISTS tokens (\n    date        TEXT NOT NULL,\n    wallet      TEXT NOT NULL,\n    chain       TEXT NOT NULL,\n    token_id    TEXT NOT NULL DEFAULT '',\n    symbol      TEXT NOT NULL DEFAULT '',\n    name        TEXT NOT NULL DEFAULT '',\n    amount      REAL NOT NULL DEFAULT 0,\n    price       REAL NOT NULL DEFAULT 0,\n    usd         REAL NOT NULL DEFAULT 0,\n    logo        TEXT NOT NULL DEFAULT '',\n    PRIMARY KEY (date, wallet, chain, token_id)\n);\nCREATE INDEX IF NOT EXISTS idx_tokens_date ON tokens(date);\nCREATE INDEX IF NOT EXISTS idx_wt_date ON wallet_totals(date);\n-- Trend aggregates, one row per (date, kind, name). The trend is read from here\n-- instead of re-parsing every snapshot's raw JSON: the page-load cost then depends\n-- on the number of *dates*, not on the number of token rows (which grows with the\n-- portfolio). Rebuilt wholesale when the blacklist or the label rules change, since\n-- those rewrite history retroactively.\nCREATE TABLE IF NOT EXISTS history_totals (\n    date  TEXT NOT NULL,\n    kind  TEXT NOT NULL,          -- 'total' | 'wallet' | 'chain'\n    name  TEXT NOT NULL DEFAULT '',\n    usd   REAL NOT NULL DEFAULT 0,\n    PRIMARY KEY (date, kind, name)\n);\nCREATE TABLE IF NOT EXISTS meta (\n    key   TEXT PRIMARY KEY,\n    value TEXT NOT NULL DEFAULT ''\n);\n\"\"\"\n\n_lock = threading.RLock()\n\n\ndef _db_path():\n    return config.DB_PATH or profiles.db_path()\n\n\n_schema_done = set()\n\n\ndef _connect():\n    \"\"\"Open the profile DB, making sure this process has created the schema.\n\n    Older databases predate history_totals/meta, and any code path may be the first\n    to touch the DB (tests, CLI fetch, the server), so the migration is applied here\n    once per file instead of relying on the caller.\n    \"\"\"\n    path = _db_path()\n    conn = sqlite3.connect(path, timeout=30)\n    conn.row_factory = sqlite3.Row\n    if path not in _schema_done:\n        conn.executescript(SCHEMA)\n        conn.commit()\n        _schema_done.add(path)\n    return conn\n\n\ndef init_db():\n    \"\"\"Create the schema for the active profile (idempotent).\"\"\"\n    with _lock:\n        conn = _connect()\n        try:\n            conn.executescript(SCHEMA)\n            conn.commit()\n        finally:\n            conn.close()\n\n\ndef save_snapshot(data):\n    \"\"\"Upsert today's snapshot (last result of the day wins) + detail rows.\"\"\"\n    with _lock:\n        conn = _connect()\n        try:\n            date = data[\"date\"]\n            now = datetime.now().isoformat(timespec=\"seconds\")\n            conn.execute(\n                \"INSERT OR REPLACE INTO snapshots(date, created_at, total_usd, by_chain, raw) \"\n                \"VALUES (?,?,?,?,?)\",\n                (date, now, data.get(\"total_usd\", 0.0),\n                 json.dumps(data.get(\"by_chain\", {})), json.dumps(data, ensure_ascii=False)),\n            )\n            conn.execute(\"DELETE FROM wallet_totals WHERE date=?\", (date,))\n            for w in data.get(\"wallets\", []):\n                conn.execute(\n                    \"INSERT INTO wallet_totals(date, wallet, usd) VALUES (?,?,?)\",\n                    (date, w[\"wallet\"], w.get(\"total_usd\", 0.0)))\n            conn.execute(\"DELETE FROM tokens WHERE date=?\", (date,))\n            for w in data.get(\"wallets\", []):\n                for t in w.get(\"tokens\", []):\n                    conn.execute(\n                        \"INSERT INTO tokens(date,wallet,chain,token_id,symbol,name,amount,price,usd,logo) \"\n                        \"VALUES (?,?,?,?,?,?,?,?,?,?)\",\n                        (date, t[\"wallet\"], t.get(\"chain\", \"\"), t.get(\"token_id\", \"\"),\n                         t.get(\"symbol\", \"\"), t.get(\"name\", \"\"), t.get(\"amount\", 0.0),\n                         t.get(\"price\", 0.0), t.get(\"usd\", 0.0), t.get(\"logo\", \"\")))\n            # trend aggregates for this date, from the same filtered view the UI uses\n            snap = dict(data)\n            snap[\"date\"] = date\n            _write_history_rows(conn, date, _history_rows_for(snap))\n            conn.execute(\"INSERT OR REPLACE INTO meta(key, value) VALUES ('history_sig', ?)\",\n                         (_history_sig(conn),))\n            conn.commit()\n        finally:\n            conn.close()\n\n\ndef get_snapshot(date):\n    with _lock:\n        conn = _connect()\n        try:\n            row = conn.execute(\"SELECT * FROM snapshots WHERE date=?\", (date,)).fetchone()\n            if not row:\n                return None\n            snap = json.loads(row[\"raw\"])\n            snap[\"created_at\"] = row[\"created_at\"]\n            return snap\n        finally:\n            conn.close()\n\n\ndef get_latest_snapshot():\n    with _lock:\n        conn = _connect()\n        try:\n            row = conn.execute(\"SELECT date FROM snapshots ORDER BY date DESC LIMIT 1\").fetchone()\n            if not row:\n                return None\n            return get_snapshot(row[\"date\"])\n        finally:\n            conn.close()\n\n\ndef get_snapshot_dates():\n    with _lock:\n        conn = _connect()\n        try:\n            rows = conn.execute(\"SELECT date, created_at, total_usd FROM snapshots ORDER BY date\").fetchall()\n            return [dict(r) for r in rows]\n        finally:\n            conn.close()\n\n\ndef _history_sig(conn):\n    \"\"\"Identity of everything the aggregates depend on.\n\n    Snapshot set + the two rule files: a blacklist or label change rewrites history,\n    so the signature changes and the next read rebuilds once.\n    \"\"\"\n    row = conn.execute(\n        \"SELECT COUNT(*) AS n, COALESCE(MAX(date), '') AS d, \"\n        \"COALESCE(MAX(created_at), '') AS c FROM snapshots\").fetchone()\n    return \"%s|%s|%s|%s|%s\" % (\n        row[\"n\"], row[\"d\"], row[\"c\"],\n        blacklist_mod._file_mtime() or \"\", assetlabels._file_mtime() or \"\")\n\n\ndef _history_rows_for(snap):\n    \"\"\"Aggregate rows for one snapshot, from the same filtered view the UI shows.\"\"\"\n    view = view_of(snap)\n    rows = [(\"total\", \"\", view[\"total_usd\"])]\n    for w in view[\"wallets\"]:\n        rows.append((\"wallet\", w[\"wallet\"], w[\"total_usd\"]))\n    for chain, usd in view[\"by_chain\"].items():\n        rows.append((\"chain\", chain, usd))\n    return rows\n\n\ndef _write_history_rows(conn, date, rows):\n    conn.execute(\"DELETE FROM history_totals WHERE date=?\", (date,))\n    conn.executemany(\n        \"INSERT OR REPLACE INTO history_totals(date, kind, name, usd) VALUES (?,?,?,?)\",\n        [(date, kind, name, usd) for kind, name, usd in rows])\n\n\ndef rebuild_history(conn):\n    \"\"\"Recompute every date's aggregates from the stored snapshots (one pass).\"\"\"\n    conn.execute(\"DELETE FROM history_totals\")\n    dates = [r[\"date\"] for r in conn.execute(\"SELECT date FROM snapshots ORDER BY date\")]\n    for d in dates:\n        raw = conn.execute(\"SELECT raw FROM snapshots WHERE date=?\", (d,)).fetchone()\n        if not raw:\n            continue\n        snap = json.loads(raw[\"raw\"])\n        snap[\"date\"] = d\n        _write_history_rows(conn, d, _history_rows_for(snap))\n    conn.execute(\"INSERT OR REPLACE INTO meta(key, value) VALUES ('history_sig', ?)\",\n                 (_history_sig(conn),))\n    conn.commit()          # the read path calls this: without a commit the rebuild\n    return len(dates)      # is rolled back on close and repeats on every request\n\n\ndef _ensure_history(conn):\n    \"\"\"Rebuild the aggregates when the rules or the snapshot set changed.\"\"\"\n    sig = _history_sig(conn)\n    row = conn.execute(\"SELECT value FROM meta WHERE key='history_sig'\").fetchone()\n    if row is None or row[\"value\"] != sig:\n        rebuild_history(conn)\n        return True\n    return False\n\n\ndef get_history(days=None):\n    \"\"\"Trend data: dates, total per day, per-wallet and per-chain series.\n\n    Computed from each snapshot's raw token rows through the blacklist-filtered\n    view, so historical totals always match the current blacklist.\n    \"\"\"\n    with _lock:\n        conn = _connect()\n        try:\n            sql = \"SELECT date FROM snapshots ORDER BY date DESC\"\n            args = []\n            if days:\n                sql += \" LIMIT ?\"\n                args.append(days)\n            dates = [r[\"date\"] for r in conn.execute(sql, args).fetchall()]\n            dates.reverse()\n            if not dates:\n                return {\"dates\": [], \"totals\": [], \"wallets\": {}, \"chains\": {}}\n            _ensure_history(conn)\n            wanted = set(dates)\n            totals_by_date = {}\n            wallets = {}\n            chains = {}\n            for r in conn.execute(\"SELECT date, kind, name, usd FROM history_totals\"):\n                if r[\"date\"] not in wanted:\n                    continue\n                if r[\"kind\"] == \"total\":\n                    totals_by_date[r[\"date\"]] = r[\"usd\"]\n                elif r[\"kind\"] == \"wallet\":\n                    wallets.setdefault(r[\"name\"], {})[r[\"date\"]] = r[\"usd\"]\n                else:\n                    chains.setdefault(r[\"name\"], {})[r[\"date\"]] = r[\"usd\"]\n            totals = [totals_by_date.get(d, 0.0) for d in dates]\n            return {\n                \"dates\": dates,\n                \"totals\": totals,\n                \"wallets\": {w: [series.get(d, 0.0) for d in dates]\n                            for w, series in wallets.items()},\n                \"chains\": {c: [series.get(d, 0.0) for d in dates]\n                           for c, series in chains.items()},\n            }\n        finally:\n            conn.close()\n\n\ndef get_tokens(date):\n    with _lock:\n        conn = _connect()\n        try:\n            rows = conn.execute(\n                \"SELECT wallet,chain,token_id,symbol,name,amount,price,usd,logo FROM tokens WHERE date=? \"\n                \"ORDER BY usd DESC\", (date,)).fetchall()\n            # classification is applied at read time, so editing the rules also\n            # reclassifies every historical snapshot\n            return assetlabels.annotate(filter_rows([dict(r) for r in rows]))\n        finally:\n            conn.close()\n\n\n# ————————————————————————————————————————————————————————————————\n# retention\n#\n# Every snapshot keeps a copy of every token row, so a profile grows by roughly\n# 0.75 MB per day (a 12-wallet profile reaches ~280 MB/year) with nothing ever\n# removed. Keep a dense recent window for the trend chart, and thin anything older\n# down to one snapshot per month so long-range history still works.\n# ————————————————————————————————————————————————————————————————\nKEEP_DAILY_DAYS = int(os.environ.get(\"PORTFOLIO_KEEP_DAILY_DAYS\", \"90\"))\nKEEP_MONTHLY = int(os.environ.get(\"PORTFOLIO_KEEP_MONTHLY\", \"24\"))\n\n\ndef plan_retention(dates, today=None, keep_days=None, keep_monthly=None):\n    \"\"\"Split dated snapshots into (keep, drop).\n\n    `dates` is any iterable of 'YYYY-MM-DD'. The newest `keep_days` calendar days\n    are all kept; older dates are thinned to the last snapshot of each month, of\n    which the newest `keep_monthly` months survive. Pure so it can be tested\n    without a database.\n    \"\"\"\n    keep_days = KEEP_DAILY_DAYS if keep_days is None else keep_days\n    keep_monthly = KEEP_MONTHLY if keep_monthly is None else keep_monthly\n    days = sorted({str(d)[:10] for d in dates})\n    if not days:\n        return [], []\n    if today is None:\n        today = datetime.now().date().isoformat()\n    cutoff = (datetime.fromisoformat(today).date() - timedelta(days=keep_days - 1)).isoformat()\n\n    keep, older = [], []\n    for d in days:\n        (keep if d >= cutoff else older).append(d)\n\n    # one representative per month for the tail: the last snapshot in that month\n    by_month = {}\n    for d in older:\n        by_month[d[:7]] = d\n    # One representative per month for the tail: the last snapshot in that month.\n    # A month already present in the dense window contributes nothing extra, so the\n    # chart never ends up with two points a few days apart.\n    represented = {d[:7] for d in keep}\n    tail_months = [m for m in sorted(by_month) if m not in represented]\n    keep_months = tail_months[-keep_monthly:] if keep_monthly > 0 else []\n    tail_keep = {by_month[m] for m in keep_months}\n    keep.extend(sorted(tail_keep))\n    # every older date that is not a chosen representative goes; deriving this from\n    # `older` rather than from the month map is what makes the split exhaustive\n    drop = [d for d in older if d not in tail_keep]\n    return sorted(keep), sorted(drop)\n\n\ndef prune_snapshots(today=None, keep_days=None, keep_monthly=None):\n    \"\"\"Delete snapshots outside the retention window; returns a summary.\"\"\"\n    with _lock:\n        conn = _connect()\n        try:\n            dates = [r[\"date\"] for r in conn.execute(\"SELECT date FROM snapshots\").fetchall()]\n            keep, drop = plan_retention(dates, today=today, keep_days=keep_days,\n                                        keep_monthly=keep_monthly)\n            for d in drop:\n                conn.execute(\"DELETE FROM tokens WHERE date=?\", (d,))\n                conn.execute(\"DELETE FROM wallet_totals WHERE date=?\", (d,))\n                conn.execute(\"DELETE FROM history_totals WHERE date=?\", (d,))\n                conn.execute(\"DELETE FROM snapshots WHERE date=?\", (d,))\n            if drop:\n                conn.execute(\"INSERT OR REPLACE INTO meta(key, value) VALUES ('history_sig', ?)\",\n                             (_history_sig(conn),))\n                conn.commit()\n            return {\"kept\": len(keep), \"dropped\": len(drop), \"dropped_dates\": drop}\n        finally:\n            conn.close()\n"
    },
    {
      "path": "tracker/views.py",
      "content": "# -*- coding: utf-8 -*-\n\"\"\"Blacklist-filtered view of a snapshot (single source of truth).\n\nTotals (wallet / total / by-chain) are always recomputed from the filtered\ntoken rows, so blacklist changes apply to every historical snapshot, not only\nnewly fetched ones. The health report is built on top of this view, so its\nnumbers can never disagree with the dashboard.\n\"\"\"\nfrom . import assetlabels\nfrom .blacklist import is_blacklisted\n\n\ndef view_of(snap, storage_map=None):\n    \"\"\"`storage_map` is {wallet name: hot|cold} from the live wallet list.\n\n    How a wallet is held is a property of the wallet, not a market fact, so the\n    live setting wins over whatever the snapshot recorded: marking a wallet cold in\n    Settings must move the health panel straight away instead of waiting for the\n    next refresh. The snapshot's own value stays as the fallback, which is what\n    keeps the class of a wallet that has since been removed.\n    \"\"\"\n    wallets = []\n    total = 0.0\n    by_chain = {}\n    for w in snap.get(\"wallets\", []):\n        name = w.get(\"wallet\") or w.get(\"name\", \"\")\n        tokens = [t for t in w.get(\"tokens\", []) if not is_blacklisted(t)]\n        wt = round(sum(float(t.get(\"usd\", 0.0)) for t in tokens), 2)\n        total += wt\n        for t in tokens:\n            c = t.get(\"chain\") or \"\"\n            if t.get(\"usd\"):\n                by_chain[c] = round(by_chain.get(c, 0.0) + float(t[\"usd\"]), 2)\n        wallets.append({\"wallet\": name,\n                        \"address\": w.get(\"address\", \"\"), \"type\": w.get(\"type\", \"\"),\n                        # a wallet that failed to fetch must be markable in the UI:\n                        # without this an error reads as \"this wallet holds nothing\"\n                        \"error\": w.get(\"error\") or None,\n                        \"notes\": w.get(\"notes\") or [],\n                        # storage class (cold/hot/cex) drives the health report; a\n                        # snapshot taken before this field existed simply has none\n                        \"storage\": (storage_map or {}).get(name) or w.get(\"storage\"),\n                        \"total_usd\": wt, \"token_count\": len(tokens)})\n    return {\"date\": snap.get(\"date\", \"\"), \"created_at\": snap.get(\"created_at\"),\n            \"total_usd\": round(total, 2), \"by_chain\": by_chain,\n            \"by_volatility\": volatility_totals(snap),\n            \"wallets\": wallets, \"token_count\": sum(w[\"token_count\"] for w in wallets)}\n\n\ndef volatility_totals(snap):\n    \"\"\"{\"stable\": usd, \"btc\": usd, \"other\": usd} over the blacklist-filtered rows.\n\n    The volatility card needs the *token* labels — one wallet can hold both a\n    stablecoin and an alt — so the rows go through the same label engine the token\n    table uses. \"other\" is everything that is neither a stablecoin nor BTC: the\n    part of the portfolio whose price actually swings.\n    \"\"\"\n    out = {assetlabels.STABLE: 0.0, assetlabels.BTC: 0.0, assetlabels.OTHER: 0.0}\n    for w in snap.get(\"wallets\", []):\n        for t in w.get(\"tokens\", []):\n            if is_blacklisted(t):\n                continue\n            usd = float(t.get(\"usd\") or 0.0)\n            if not usd:\n                continue\n            label = assetlabels.classify(t)\n            if label in (assetlabels.STABLE, assetlabels.BTC):\n                out[label] = round(out[label] + usd, 2)\n            else:\n                out[assetlabels.OTHER] = round(out[assetlabels.OTHER] + usd, 2)\n    return out\n"
    },
    {
      "path": "tracker/sources.py",
      "content": "# -*- coding: utf-8 -*-\n\"\"\"Configurable API sources with multi-provider failover.\n\nEvery external API (URLs + keys) lives in portfolio_sources.json\n(auto-generated with defaults on first run; edits take effect without\nrestart — the file is re-read when it changes).\n\nEach source may define several providers tried in order:\n  - an enabled provider is skipped when it throws or returns an empty result,\n    and the next enabled provider is used automatically;\n  - the last working provider per source is remembered, so subsequent calls\n    start from it and only fall back when it fails again.\n\nEnv overrides (highest priority, applied at load time):\n  DEBANK_API_KEY, BIRDEYE_API_KEY, COINGECKO_API_KEY, SOLANA_RPC\n\"\"\"\nimport json\nimport os\nimport re\nimport threading\n\nfrom . import atomicio, config, profiles\n\n_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n_DEFAULTS = {\n    \"debank\": {\n        \"enabled\": True,\n        \"chain_list_url\": \"https://api.debank.com/chain/list\",\n        \"providers\": [\n            {\"name\": \"debank-pro\", \"type\": \"pro\", \"key\": \"\",\n             \"base_url\": \"https://pro-openapi.debank.com\", \"paid\": True, \"enabled\": True},\n            {\"name\": \"debank-public\", \"type\": \"public\", \"key\": \"\",\n             \"base_url\": \"https://api.debank.com\", \"paid\": False, \"enabled\": True},\n        ],\n    },\n    \"btc\": {\n        \"enabled\": True,\n        \"providers\": [\n            {\"name\": \"blockchain.info\", \"type\": \"batch\",\n             \"url\": \"https://blockchain.info/balance\", \"enabled\": True},\n            {\"name\": \"mempool.space\", \"type\": \"per_address\",\n             \"url\": \"https://mempool.space/api/address/{addr}\", \"enabled\": True},\n        ],\n    },\n    \"doge\": {\n        \"enabled\": True,\n        \"providers\": [\n            {\"name\": \"blockcypher\", \"type\": \"per_address\",\n             \"url\": \"https://api.blockcypher.com/v1/doge/main/addrs/{addr}/balance\", \"enabled\": True},\n        ],\n    },\n    \"ada\": {\n        \"enabled\": True,\n        \"providers\": [\n            {\"name\": \"koios\", \"type\": \"batch\",\n             \"url\": \"https://api.koios.rest/api/v1/address_info\",\n             \"stake_url\": \"https://api.koios.rest/api/v1/account_info\", \"enabled\": True},\n        ],\n    },\n    \"prices\": {\n        \"enabled\": True,\n        \"providers\": [\n            {\"name\": \"coingecko\", \"type\": \"batch\",\n             \"url\": \"https://api.coingecko.com/api/v3/simple/price\", \"key\": \"\", \"enabled\": True},\n            {\"name\": \"binance\", \"type\": \"batch\",\n             \"url\": \"https://api.binance.com/api/v3/ticker/price\", \"enabled\": True},\n            {\"name\": \"coinbase\", \"type\": \"per_pair\",\n             \"url\": \"https://api.coinbase.com/v2/prices/{pair}-USD/spot\", \"enabled\": True},\n            {\"name\": \"okx\", \"type\": \"per_pair\",\n             \"url\": \"https://www.okx.com/api/v5/market/ticker\", \"enabled\": True},\n        ],\n    },\n    \"solana\": {\n        \"enabled\": True,\n        \"rpc\": [\n            {\"name\": \"mainnet-beta\", \"url\": \"https://api.mainnet-beta.solana.com\", \"enabled\": True},\n            {\"name\": \"ankr-public\", \"url\": \"https://rpc.ankr.com/solana\", \"enabled\": True},\n        ],\n        \"spl_prices\": {\n            \"providers\": [\n                {\"name\": \"dexscreener\", \"type\": \"batch\",\n                 \"url\": \"https://api.dexscreener.com/latest/dex/tokens/{mints}\", \"enabled\": True},\n                {\"name\": \"coingecko\", \"type\": \"per_mint\",\n                 \"url\": \"https://api.coingecko.com/api/v3/simple/token_price/solana\",\n                 \"key\": \"\", \"enabled\": True},\n            ],\n        },\n        \"birdeye\": {\n            \"enabled\": False,\n            \"key\": \"\",\n            \"url\": \"https://public-api.birdeye.so/defi/wallet_tokens\",\n        },\n    },\n    \"hyperliquid\": {\n        \"enabled\": True,\n        \"providers\": [\n            {\"name\": \"api.hyperliquid.xyz\", \"url\": \"https://api.hyperliquid.xyz/info\", \"enabled\": True},\n            {\"name\": \"hyperliquid-api.mainnet\", \"url\": \"https://hyperliquid-api.mainnet.hyperliquid.xyz/info\", \"enabled\": True},\n        ],\n    },\n    \"etherscan\": {\n        \"enabled\": True,\n        \"api_key\": \"\",\n        \"chains\": [\"eth\"],\n    },\n    \"cex\": {\n        \"enabled\": True,\n        \"accounts\": [],\n    },\n}\n\n_cache = {\"mtime\": None, \"data\": None}\n_last_ok = {}          # source_key -> provider index of last success\n_lock = threading.RLock()\n\n\ndef sources_file():\n    return profiles.sources_file()\n\n\ndef _deep_merge(base, override):\n    out = dict(base)\n    for k, v in (override or {}).items():\n        if isinstance(v, dict) and isinstance(base.get(k), dict):\n            out[k] = _deep_merge(base[k], v)\n        else:\n            out[k] = v\n    return out\n\n\ndef load(force=False):\n    \"\"\"Merged config; re-reads the file whenever it changes on disk.\"\"\"\n    global _cache\n    with _lock:\n        try:\n            mtime = os.path.getmtime(profiles.sources_file()) if os.path.exists(profiles.sources_file()) else None\n        except OSError:\n            mtime = None\n        if force or _cache[\"data\"] is None or _cache[\"mtime\"] != mtime:\n            user = {}\n            if os.path.exists(profiles.sources_file()):\n                try:\n                    with open(profiles.sources_file(), \"r\", encoding=\"utf-8\") as f:\n                        user = json.load(f) or {}\n                except Exception:  # noqa: BLE001\n                    user = {}\n            data = _deep_merge(_DEFAULTS, user)\n            _normalize(data)\n            _apply_env(data)\n            _cache = {\"mtime\": mtime, \"data\": data}\n        return _cache[\"data\"]\n\n\ndef _normalize(data):\n    \"\"\"Backward compatibility: old debank {key, base_url} -> pro provider.\"\"\"\n    db = data.get(\"debank\") or {}\n    if not db.get(\"providers\"):\n        db[\"providers\"] = [\n            {\"name\": \"debank-pro\", \"type\": \"pro\",\n             \"key\": db.get(\"key\") or \"\",\n             \"base_url\": db.get(\"base_url\") or \"https://pro-openapi.debank.com\",\n             \"paid\": True, \"enabled\": True},\n        ]\n    # if the top-level key holds a value the pro provider lacks, copy it over\n    top_key = db.get(\"key\") or \"\"\n    if top_key:\n        for p in db.get(\"providers\", []):\n            if p.get(\"type\") == \"pro\" and not p.get(\"key\"):\n                p[\"key\"] = top_key\n\n\ndef _apply_env(data):\n    env = os.environ\n    if env.get(\"DEBANK_API_KEY\"):\n        data[\"debank\"][\"key\"] = env[\"DEBANK_API_KEY\"].strip()\n        for p in data[\"debank\"].get(\"providers\", []):\n            if p.get(\"type\") == \"pro\":\n                p[\"key\"] = env[\"DEBANK_API_KEY\"].strip()\n                p[\"enabled\"] = True\n    if env.get(\"BIRDEYE_API_KEY\"):\n        bd = data[\"solana\"][\"birdeye\"]\n        bd[\"key\"] = env[\"BIRDEYE_API_KEY\"].strip()\n        bd[\"enabled\"] = True\n    if env.get(\"COINGECKO_API_KEY\"):\n        for p in data[\"prices\"][\"providers\"] + data[\"solana\"][\"spl_prices\"][\"providers\"]:\n            if p.get(\"name\") == \"coingecko\":\n                p[\"key\"] = env[\"COINGECKO_API_KEY\"].strip()\n    if env.get(\"SOLANA_RPC\"):\n        data[\"solana\"][\"rpc\"].insert(0, {\"name\": \"env\", \"url\": env[\"SOLANA_RPC\"].strip(), \"enabled\": True})\n    # CEX account env overrides: <EX>_API_KEY/SECRET (+ _PASSPHRASE for OKX/Bitget)\n    cex_accounts = data.get(\"cex\", {}).get(\"accounts\", [])\n    for ex, envk, envs, envp in ((\"binance\", \"BINANCE_API_KEY\", \"BINANCE_API_SECRET\", None),\n                                 (\"bybit\", \"BYBIT_API_KEY\", \"BYBIT_API_SECRET\", None),\n                                 (\"backpack\", \"BACKPACK_API_KEY\", \"BACKPACK_API_SECRET\", None),\n                                 (\"okx\", \"OKX_API_KEY\", \"OKX_API_SECRET\", \"OKX_API_PASSPHRASE\"),\n                                 (\"bitget\", \"BITGET_API_KEY\", \"BITGET_API_SECRET\",\n                                  \"BITGET_API_PASSPHRASE\")):\n        if env.get(envk) and env.get(envs):\n            found = next((a for a in cex_accounts if a.get(\"exchange\") == ex), None)\n            entry = {\"name\": f\"{ex}_env\", \"exchange\": ex,\n                     \"key\": env[envk].strip(), \"secret\": env[envs].strip(), \"enabled\": True}\n            if envp and env.get(envp):\n                entry[\"passphrase\"] = env[envp].strip()\n            if found:\n                found.update(entry)\n            else:\n                cex_accounts.append(entry)\n\n\ndef ensure_file():\n    \"\"\"Write the default config file if it does not exist yet.\"\"\"\n    if not os.path.exists(profiles.sources_file()):\n        with _lock:\n            atomicio.write_json(profiles.sources_file(), _DEFAULTS)\n\n\ndef save(cfg):\n    \"\"\"Persist a user-supplied config.\n\n    The written file is always the full merged config (defaults + previous\n    file + this update), so partial updates never leave the file incomplete.\n    \"\"\"\n    with _lock:\n        current = {}\n        if os.path.exists(profiles.sources_file()):\n            try:\n                with open(profiles.sources_file(), \"r\", encoding=\"utf-8\") as f:\n                    current = json.load(f) or {}\n            except Exception:  # noqa: BLE001\n                current = {}\n        merged = _deep_merge(_DEFAULTS, _deep_merge(current, cfg if isinstance(cfg, dict) else {}))\n        atomicio.write_json(profiles.sources_file(), merged)\n        load(force=True)\n\n\ndef get_source(name):\n    return load().get(name) or {}\n\n\n# ————————————————————————————————————————————————————————————————\n# secret masking\n#\n# GET /api/sources used to hand the raw API keys to the browser, so anything that\n# could reach the loopback port (another local process, a log dump, a screenshot)\n# saw them in the clear. The API now returns a masked stub by default and reveals\n# only on an explicit request. The stub keeps a 4-char prefix/suffix so the UI can\n# still show WHICH key is configured, and merge_masked guarantees a stub is never\n# written back over the real key.\n# ————————————————————————————————————————————————————————————————\nMASK = \"\\u2026\"                                   # …\n_SECRET_KEYS = (\"key\", \"secret\", \"api_key\", \"apikey\", \"password\", \"token\")\n# secrets embedded in a URL query, e.g. https://host/?api-key=<uuid>\n_SECRET_IN_URL = re.compile(r\"([?&](?:api[-_]?key|apikey|key|token)=)([^&\\s]+)\", re.I)\n\n\ndef mask_secret(value):\n    \"\"\"Recognisable stub for a secret: 'cdd7…8e1e', or a bare '…' when short.\"\"\"\n    v = \"\" if value is None else str(value)\n    if not v:\n        return \"\"\n    if len(v) <= 8:\n        return MASK\n    return v[:4] + MASK + v[-4:]\n\n\ndef is_masked(value):\n    return MASK in str(value if value is not None else \"\")\n\n\ndef mask_url(value):\n    \"\"\"Mask the secret part of a URL query string, leaving the rest readable.\"\"\"\n    return _SECRET_IN_URL.sub(lambda m: m.group(1) + mask_secret(m.group(2)), str(value))\n\n\ndef mask_config(cfg):\n    \"\"\"Deep copy of the config with every API key / secret replaced by a stub.\"\"\"\n    if isinstance(cfg, dict):\n        out = {}\n        for k, v in cfg.items():\n            if isinstance(v, (dict, list)):\n                out[k] = mask_config(v)\n            elif isinstance(v, str):\n                out[k] = mask_secret(v) if k.lower() in _SECRET_KEYS else mask_url(v)\n            else:\n                out[k] = v\n        return out\n    if isinstance(cfg, list):\n        return [mask_config(v) for v in cfg]\n    return cfg\n\n\ndef merge_masked(incoming, current):\n    \"\"\"Replace masked stubs in `incoming` with the real values from `current`.\n\n    The settings form round-trips whatever the API gave it, so without this a save\n    would overwrite a live API key with the literal string 'cdd7…8e1e'. Any string\n    carrying the mask character is treated as \"unchanged\" — a real secret a human\n    typed can never contain it.\n    \"\"\"\n    if isinstance(incoming, dict):\n        out = {}\n        for k, v in incoming.items():\n            cur = current.get(k) if isinstance(current, dict) else None\n            if isinstance(v, (dict, list)):\n                out[k] = merge_masked(v, cur if isinstance(cur, (dict, list)) else ({} if isinstance(v, dict) else []))\n            elif isinstance(v, str) and is_masked(v) and isinstance(cur, str) and cur:\n                out[k] = cur\n            else:\n                out[k] = v\n        return out\n    if isinstance(incoming, list):\n        cur_list = current if isinstance(current, list) else []\n        out = []\n        for i, v in enumerate(incoming):\n            cur = cur_list[i] if i < len(cur_list) else None\n            if isinstance(v, (dict, list)):\n                out.append(merge_masked(v, cur if isinstance(cur, (dict, list)) else ({} if isinstance(v, dict) else [])))\n            else:\n                out.append(v)\n        return out\n    return incoming\n\n\ndef provider_order(source_key, providers):\n    \"\"\"Enabled providers, last-successful first (failover-aware order).\"\"\"\n    with _lock:\n        last = _last_ok.get(source_key)\n    enabled = [(i, p) for i, p in enumerate(providers) if p.get(\"enabled\", True)]\n    if last is not None:\n        enabled.sort(key=lambda ip: (0 if ip[0] == last else 1, ip[0]))\n    return [p for _, p in enabled]\n\n\ndef try_providers(source_key, providers, fetch_one, nonempty=False):\n    \"\"\"Run fetch_one(p) over enabled providers until one succeeds.\n\n    nonempty=True treats a falsy result (None/{}[]) as failure and keeps trying.\n    Returns (result, provider); raises the last error when all providers fail.\n    \"\"\"\n    last_err = None\n    for p in provider_order(source_key, providers):\n        try:\n            result = fetch_one(p)\n            if nonempty and not result:\n                raise ValueError(\"empty result from provider\")\n            with _lock:\n                _last_ok[source_key] = providers.index(p)\n            return result, p\n        except Exception as e:  # noqa: BLE001\n            last_err = e\n            continue\n    if last_err is None:\n        raise RuntimeError(f\"source '{source_key}': no enabled provider\")\n    raise last_err\n\n\ndef reset_failover():\n    with _lock:\n        _last_ok.clear()\n\n\ndef failover_state():\n    \"\"\"{source_key: index of last successful provider} for display.\"\"\"\n    with _lock:\n        return dict(_last_ok)\n"
